-- RLS for kon-crm after the English rename: functions, triggers and policies come back with the new names.
--
-- The previous file dropped the old ones; between both files the tables stay closed, not open.

-- Policies, with the new names and the core's English helpers.
DROP POLICY IF EXISTS crm_activities_team ON crm_activities;
CREATE POLICY crm_activities_team ON crm_activities AS PERMISSIVE FOR ALL USING ((((COALESCE(current_setting('app.current_user_id'::text, true), ''::text) = ''::text) AND (COALESCE(current_setting('app.current_user_role'::text, true), ''::text) = ''::text)) OR (current_setting('app.current_user_role'::text, true) = ANY (ARRAY['admin'::text, 'editor'::text, 'agent'::text])))) WITH CHECK ((((COALESCE(current_setting('app.current_user_id'::text, true), ''::text) = ''::text) AND (COALESCE(current_setting('app.current_user_role'::text, true), ''::text) = ''::text)) OR (current_setting('app.current_user_role'::text, true) = ANY (ARRAY['admin'::text, 'editor'::text, 'agent'::text]))));
